public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    permuteHelper(nums, result, new ArrayList<>());
    return result;
}

private void permuteHelper(int[] nums, List<List<Integer>> result, List<Integer> currResult) {
    if (currResult.size() == nums.length) {
        result.add(new ArrayList<>(currResult));
        return;
    }

    for (int i = 0; i < nums.length; i++) {
        if (contains(currResult, nums[i])) continue;
        currResult.add(nums[i]);
        permuteHelper(nums, result, currResult);
        currResult.remove(currResult.size() - 1);
    }
}

