public int findLargestSubstring(List<String> strings) {
    // Initialize variables to keep track of the largest substring and its inverse
    int largestSubstring = 0;
    String largestSubstringInverse = "";

    // Iterate over each string in the input list
    for (String s : strings) {
        // If the string is empty, return 0
        if (s.isEmpty()) {
            return 0;
        }

        // Get the length of the string and its inverse
        int sLength = s.length();
        int sInverseLength = sLength / 2;

        // Get the substring of the string from the beginning to the end
        String sSubstring = s.substring(0, sLength);

        // Get the substring of the string from the end to the beginning
        String sInverseSubstring = s.substring(sInverseLength, sLength);

        // Check if the substring or its inverse is already the largest substring
        if (sSubstring.length() > largestSubstring || sInverseSubstring.length() > largestSubstring) {
            largestSubstring = Math.max(sSubstring.length(), sInverseSubstring.length());
            largestSubstringInverse = sInverseSubstring.length() > largestSubstring ? sInverseSubstring : sSubstring;
        }
    }

    // Return the length of the largest substring or its inverse
    return largestSubstringInverse.length();
}

