public int search(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        if (nums[left] <= nums[mid]) {
            // left to mid is a sorted subarray
            if (nums[left] <= target && target <= nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            // mid to right is a sorted subarray
            if (nums[mid] <= target && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    // Calculate the 5% threshold for number of elements to remove from each end
    int threshold = (int) (0.05 * arr.length);

    // Find the smallest and largest elements in the array
    int smallest = Integer.MAX_VALUE;
    int largest = Integer.MIN_VALUE;

    for (int i = 0; i < arr.length; i++) {
        if (arr[i] < smallest) {
            smallest = arr[i];
        }
        if (arr[i] > largest) {
            largest = arr[i];
        }
    }

    // Remove the smallest and largest elements from the array
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] == smallest) {
            arr[i] = 0;
            threshold--;
        }
        if (arr[i] == largest) {
            arr[i] = 0;
            threshold--;
        }
    }

    // Calculate the mean of the remaining elements
    double mean = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] != 0) {
            mean += arr[i];
        }
    }

    mean /= arr.length - 2 * threshold;

    return mean;
}

public boolean canArrange(int[] arr, int k) {
    // Initialize a hash map to keep track of the remainder of each element when divided by k
    Map<Integer, Integer> remainderCount = new HashMap<>();

    // Loop through the array and increment the count of each remainder
    for (int elem : arr) {
        int remainder = elem % k;
        if (remainderCount.containsKey(remainder)) {
            remainderCount.put(remainder, remainderCount.get(remainder) + 1);
        } else {
            remainderCount.put(remainder, 1);
        }
    }

    // Check if there are more elements with remainder 0 than k/2
    int count0 = remainderCount.getOrDefault(0, 0);
    if (count0 > k / 2) {
        return false;
    }

    // Check if there is an odd number of elements with the same remainder as k/2
    int count2 = 0;
    for (int count : remainderCount.values()) {
        if (count % 2 != 0) {
            count2++;
        }
    }
    return count2 <= 1;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
  int[] time = new int[n];
  boolean[] visited = new boolean[n];

  for (int i = 0; i < n; i++) {
    if (!visited[i] && hasApple[i]) {
      dfs(i, time, visited, edges, hasApple);
    }
  }

  int min = 0;
  for (int i = 0; i < n; i++) {
    if (hasApple[i]) {
      min = Math.max(min, time[i]);
    }
  }

  return min;
}

private void dfs(int curr, int[] time, boolean[] visited, int[][] edges, boolean[] hasApple) {
  visited[curr] = true;
  int children = 0;
  for (int i = 0; i < edges[curr].length; i++) {
    int child = edges[curr][i];
    if (!visited[child] && hasApple[child]) {
      dfs(child, time, visited, edges, hasApple);
      children++;
    }
  }

  if (children > 0) {
    time[curr] = time[curr] + children + 1;
  }
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return "";
    }

    Character[] sortedChars = new Character[s.length()];
    List<Character> charList = new ArrayList<>(s.length());
    for (char c : s.toCharArray()) {
        charList.add(c);
    }
    Collections.sort(charList);

    int smallest = 0;
    int largest = charList.size() - 1;

    while (smallest < charList.size() && largest >= 0) {
        sortedChars[smallest] = charList.get(smallest);
        sortedChars[largest] = charList.get(largest);

        smallest++;
        largest--;
    }

    for (int i = smallest; i < sortedChars.length; i++) {
        sortedChars[i] = charList.get(i);
    }

    for (int i = largest; i >= 0; i--) {
        sortedChars[i] = charList.get(i);
    }

    return new String(sortedChars);
}

public boolean splitArraySameAverage(int[] nums) {
    // Calculate the sum of the input array
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Calculate the average of the input array
    int average = sum / nums.length;

    // Split the input array into two arrays
    int[] left = new int[nums.length / 2];
    int[] right = new int[nums.length - left.length];
    for (int i = 0; i < nums.length; i++) {
        if (i < left.length) {
            left[i] = nums[i];
        } else {
            right[i - left.length] = nums[i];
        }
    }

    // Calculate the sum of the left and right arrays
    int leftSum = 0;
    for (int num : left) {
        leftSum += num;
    }
    int rightSum = 0;
    for (int num : right) {
        rightSum += num;
    }

    // Check if the left and right arrays have the same average
    return leftSum == rightSum && leftSum == average * left.length;
}

