public int findMinFibonacciNumbers(int k) {
    if (k <= 1) {
        return k;
    }

    int[] fib = new int[k]; // an array to store the Fibonacci numbers
    fib[0] = 1; // the first Fibonacci number is 1
    fib[1] = 1; // the second Fibonacci number is 1
    int i = 2; // the index for the current Fibonacci number
    while (i < k) { // while the current Fibonacci number is less than the target sum
        fib[i] = fib[i - 1] + fib[i - 2]; // add the previous two Fibonacci numbers to get the next Fibonacci number
        if (fib[i] == k) { // if the current Fibonacci number is the target sum
            return i + 1; // return the index of the current Fibonacci number (which is equal to the target sum)
        }
        i++; // increment the index to the next Fibonacci number
    }

    return i; // return the index of the current Fibonacci number (which is greater than the target sum)
}

public int kthFactor(int n, int k) {
    // Initialize a list to store all the factors of n
    List<Integer> factors = new ArrayList<>();

    // Iterate from 1 to the square root of n
    for (int i = 1; i * i <= n; i++) {
        // If i is a factor of n, add it to the list
        if (n % i == 0) {
            factors.add(i);
            // If i is not equal to n / i, add n / i to the list
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }

    // Sort the list of factors in ascending order
    Collections.sort(factors);

    // If the list size is less than k, return -1
    if (factors.size() < k) {
        return -1;
    }

    // Return the kth factor
    return factors.get(k - 1);
}

