}

private static boolean isSteppingNumber(int num) {
    // Get the digits of the number
    String digits = String.valueOf(num);

    // Check if the number is a stepping number
    for (int i = 0; i < digits.length() - 1; i++) {
        // Get the current digit and the next digit
        int currDigit = digits.charAt(i) - '0';
        int nextDigit = digits.charAt(i + 1) - '0';

        // Check if the current digit is one more or one less than the next digit
        if (currDigit != nextDigit - 1 && currDigit != nextDigit + 1) {
            return false;
        }
    }

    return true;
}

