    int longestLineLength = 0;
    int longestLineIndex = -1;

    // Loop through each row of the matrix
    for (int i = 0; i < mat.length; i++) {
        // Initialize a variable to keep track of the current line length
        int currentLineLength = 0;

        // Loop through each column of the row
        for (int j = 0; j < mat[i].length; j++) {
            // If the current element is 1, increment the line length
            if (mat[i][j] == 1) {
                currentLineLength++;
            }

            // If the current element is 0, reset the line length
            else {
                currentLineLength = 0;
            }

            // If the current line length is longer than the longest line length, update the longest line length and its index
            if (currentLineLength > longestLineLength) {
                longestLineLength = currentLineLength;
                if (mat[i][j] == 1) {
                    longestLineIndex = i;
                }
            }
        }
    }

    // Return the length of the longest line
    return longestLineLength;
}

