public static int largestRectangleArea(int[] heights) {
    int area = 0;
    for (int i = 0; i < heights.length; i++) {
        int maxHeight = 0;
        for (int j = i; j < heights.length; j++) {
            maxHeight = Math.max(maxHeight, heights[j]);
            area = Math.max(area, maxHeight * (j - i + 1));
        }
    }
    return area;
}

public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows + cols - 1];
    int count = 0;
    for (int i = 0; i < rows && i < cols; i++) {
        result[count++] = mat[i][i];
    }
    for (int i = 0; i < rows && i + 1 < cols; i++) {
        result[count++] = mat[i][cols - 1 - i];
    }
    for (int i = cols - 2; i >= rows && i >= 0; i--) {
        result[count++] = mat[rows - 1][i];
    }
    for (int i = rows - 2; i >= 1; i--) {
        result[count++] = mat[i][0];
    }
    return result;
}

public static int findSmallestInteger(int n) {
    // Find the smallest integer that can be formed by rearranging the digits of n
    if (n < 10) {
        return -1; // no possible solution
    }
    int smallest = -1;
    int[] digits = new int[10];
    int[] counts = new int[10];
    for (int i = 0; i < 10; i++) {
        counts[i] = n % 10;
        n /= 10;
    }
    for (int i = 0; i < 10; i++) {
        for (int j = 0; j < counts[i]; j++) {
            smallest = i;
        }
    }
    return smallest;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n < 1) {
        return result;
    }
    int mid = (int) Math.pow(10, n - 1);
    for (int i = 0; i < n; i++) {
        int start = mid - (int) Math.pow(10, i);
        int end = mid + (int) Math.pow(10, i);
        for (int j = start; j < end; j++) {
            String num = String.valueOf(j);
            if (num.length() == n && isCenterSymmetric(num)) {
                result.add(num);
            }
        }
    }
    return result;
}

private static boolean isCenterSymmetric(String num) {
    for (int i = 0; i < num.length() / 2; i++) {
        if (num.charAt(i) != num.charAt(num.length() - 1 - i)) {
            return false;
        }
    }
    return true;
}

public static boolean isBoomerang(int[][] points) {
  if (points == null || points.length != 3) {
    throw new IllegalArgumentException("points must be a non-null array of length 3");
  }

  int aX = points[0][0];
  int aY = points[0][1];
  int bX = points[1][0];
  int bY = points[1][1];
  int cX = points[2][0];
  int cY = points[2][1];

  int crossProduct = (bX - aX) * (cY - aY) - (bY - aY) * (cX - aX);
  if (crossProduct < 0) {
    return false;
  }

  int distance1 = (aX - bX) * (aX - bX) + (aY - bY) * (aY - bY);
  int distance2 = (aX - cX) * (aX - cX) + (aY - cY) * (aY - cY);
  int distance3 = (bX - cX) * (bX - cX) + (bY - cY) * (bY - cY);
  return distance1 >= distance2 + distance3;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The input must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int nextUglyNumberIndex = 1;
    int[] factors = new int[]{2, 3, 5};

    for (int i = 1; i < n; i++) {
        int minFactor = factors[0];
        for (int j = 1; j < factors.length; j++) {
            if (uglyNumbers[nextUglyNumberIndex - 1] * factors[j] < uglyNumbers[nextUglyNumberIndex - 1] * minFactor) {
                minFactor = factors[j];
            }
        }
        uglyNumbers[nextUglyNumberIndex++] = uglyNumbers[nextUglyNumberIndex - 1] * minFactor;
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
          if (s == null || s.isEmpty()) {
              return 0;
          }

          int longestNonEmptySubstring = 0;
          int currentLength = 0;
          char currentCharacter = s.charAt(0);
          for (int i = 1; i < s.length(); i++) {
              if (s.charAt(i) == currentCharacter) {
                  currentLength++;
              } else {
                  if (currentLength > longestNonEmptySubstring) {
                      longestNonEmptySubstring = currentLength;
                  }
                  currentLength = 0;
                  currentCharacter = s.charAt(i);
              }
          }

          if (currentLength > longestNonEmptySubstring) {
              longestNonEmptySubstring = currentLength;
          }

          return longestNonEmptySubstring;
      }

