public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNums = new HashSet<>();
    int sum = 0;
    for (int num : nums) {
        if (!uniqueNums.contains(num)) {
            sum += num;
            uniqueNums.add(num);
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
	// Initialize a map to store the number of perfect squares
	// that add up to a given number
	Map<Integer, Integer> perfectSquareCounts = new HashMap<>();

	// Initialize the minimum number of perfect squares
	int min = 0;

	// Iterate from 1 to n
	for (int i = 1; i <= n; i++) {
		// Get the perfect square that is closest to the current number
		int perfectSquare = (int)Math.floor(Math.sqrt(i));

		// If the current number is a perfect square, increment the minimum
		// number of perfect squares by 1
		if (perfectSquare * perfectSquare == i) {
			min++;
		// If the current number is not a perfect square, increment the
		// number of perfect squares that add up to the current number
		} else {
			int count = perfectSquareCounts.getOrDefault(i, 0);
			perfectSquareCounts.put(i, count + 1);
		}
	}

	// Return the minimum number of perfect squares
	return min;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedSentence = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder();
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord.append(word.charAt(i));
        }
        reversedSentence.append(reversedWord.toString());
        reversedSentence.append(" ");
    }

    // Trim the last space and return the result
    return reversedSentence.toString().replaceAll("( )+", " ").trim();
}
